head.script:
scwin.onpageload = function () {
    dlt_a.setJSON([
        { "name" : "홍길동", "colA" : "01012345678", "colB" : "01012345678", "colC" : "01012345678" },
        { "name" : "김철수", "colA" : "01098765432", "colB" : "01098765432", "colC" : "01098765432" }
    ]);

    // console 오류를 결과창에도 출력 (첫 줄만)
    let orgError = console.error;
    console.error = function () {
        for (let i = 0; i < arguments.length; i++) {
            let msg = String(arguments[i] && arguments[i].message !== undefined ? arguments[i].name + ": " + arguments[i].message : arguments[i]).split("\n")[0];
            if (msg.indexOf("TypeError") > -1) {
                scwin.setReturnValue("    console 오류 : " + msg);
                break;
            }
        }
        return orgError.apply(console, arguments);
    };
};

// 결과 출력용 구분 ([A] colA / [B] colB / [C] colC)
scwin.getTag = function (colId) {
    if (colId === "colA") {
        return "[A] ";
    }
    if (colId === "colB") {
        return "[B] ";
    }
    if (colId === "colC") {
        return "[C] ";
    }
    return "";
};

// 홍길동 행의 A, B, C Column getCellDisplayData 결과 출력
scwin.btn_get_onclick = function (e) {
    let arr = ["colA", "colB", "colC"];
    for (let i = 0; i < arr.length; i++) {
        let tag = scwin.getTag(arr[i]);
        scwin.setReturnValue(tag + "getCellDisplayData(0, \"" + arr[i] + "\") 호출");
        try {
            let value = grd_a.getCellDisplayData(0, arr[i]);
            scwin.setReturnValue("    반환값 : " + (value === undefined ? "undefined" : "'" + value + "'"));
        } catch (err) {
            scwin.setReturnValue("    예외 : " + err.message);
        }
    }
};

// 리턴 값 초기화
scwin.btn_clear_onclick = function (e) {
    tbx_return.setValue("");
};

// 리턴 값 설정
scwin.setReturnValue = function (strValue) {
    tbx_return.setValue(tbx_return.getValue() + strValue);
    tbx_return.setValue(tbx_return.getValue() + "\n");
};
